package per.chowh.bot.utils;import cn.hutool.extra.spring.SpringUtil;import lombok.extern.slf4j.Slf4j;import okhttp3.*;import per.chowh.bot.config.ChowhBotConfig;import per.chowh.bot.ext.dict.service.DataDictService;import tools.jackson.databind.JsonNode;import java.io.IOException;import java.net.InetSocketAddress;import java.net.Proxy;import java.net.http.HttpClient;import java.time.Duration;import java.util.Map;/** * @author : Chowhound * @since : 2025/10/21 - 14:46 */@Slf4jpublic class HttpProxyUtils{    public static final String PROXY_DOMAINS = "PROXY_DOMAINS";    private static DataDictService dataDictService;    private static OkHttpClient BASE_CLIENT;    static {        String host = ConfigUtils.getConfig("per.network.proxy.host");        String port = ConfigUtils.getConfig("per.network.proxy.port");        if (host != null && !host.isBlank() && port != null && !port.isBlank()) {            Proxy proxy = new Proxy(Proxy.Type.HTTP, new InetSocketAddress(host, Integer.parseInt(port)));            BASE_CLIENT = new OkHttpClient.Builder()                    .proxy(proxy)                    .callTimeout(Duration.ofSeconds(60))                    .connectTimeout(Duration.ofSeconds(60))                    .readTimeout(Duration.ofSeconds(60))                    .writeTimeout(Duration.ofSeconds(60))                    .build();            log.info("HttpProxyUtils代理地址 host: {}, port: {}",  host, port);        }    }    public static String doGetStr(String url) throws IOException {        return HttpUtils.doGetStr(BASE_CLIENT, url, null);    }    public static byte[] doGetBytes(String url) throws IOException {        return HttpUtils.doGetBytes(BASE_CLIENT, url, null);    }    public static byte[] doGetBytes(String url, boolean autoProxy) throws IOException {        return HttpUtils.doGetBytes(getOkHttpClient(url, autoProxy), url, null);    }    public static Response doGet(String url) throws IOException {        if (BASE_CLIENT == null) {            throw new IOException("HTTP proxy is not configured");        }        return HttpUtils.doGet(BASE_CLIENT, url, null);    }    public static JsonNode doGetJson(String url) throws IOException {        return HttpUtils.doGetJson(BASE_CLIENT, url);    }    private static OkHttpClient getOkHttpClient(String url, boolean autoProxy) {        HttpUrl httpUrl = HttpUrl.parse(url);        if (httpUrl == null) {            return null;        }        OkHttpClient client = null;        if (autoProxy) {            DataDictService dictService = getDataDictService();            boolean useProxy = dictService.listDetails(PROXY_DOMAINS)                    .stream()                    .anyMatch(entry -> httpUrl.host().equalsIgnoreCase(entry.getDictName()));            if (useProxy) {                client = BASE_CLIENT;            }        }        return client;    }    private static DataDictService getDataDictService() {        if (dataDictService == null && ChowhBotConfig.APPLICATION_CONTEXT != null) {            dataDictService = ChowhBotConfig.APPLICATION_CONTEXT.getBean(DataDictService.class);        }        return dataDictService;    }}